alter table public.shopping_items add column if not exists note text check (note is null or char_length(note) <= 40);
alter table public.shopping_items add column if not exists list text not null default 'super' check (list in ('super','drogerie','markt'));
alter table public.shopping_items add column if not exists assigned_to uuid references auth.users(id) on delete set null;
alter table public.meal_plan add column if not exists cook uuid references auth.users(id) on delete set null;
alter table public.meal_plan add column if not exists slot text not null default 'abend' check (slot in ('frueh','mittag','abend'));
alter table public.meal_plan add column if not exists label text check (label is null or char_length(label) <= 40);
alter table public.meal_plan drop constraint if exists meal_plan_pkey;
alter table public.meal_plan add primary key (family_id, day, slot);
alter table public.polls add column if not exists ends_at timestamptz;
create table if not exists public.recipe_notes (id uuid primary key default gen_random_uuid(), family_id uuid not null references public.families(id) on delete cascade, recipe_id text not null, user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, body text not null check (char_length(body) between 1 and 200), created_at timestamptz not null default now());
alter table public.recipe_notes enable row level security;
drop policy if exists "notizen lesen" on public.recipe_notes;
create policy "notizen lesen" on public.recipe_notes for select using (public.is_member(family_id));
drop policy if exists "notizen schreiben" on public.recipe_notes;
create policy "notizen schreiben" on public.recipe_notes for insert with check (public.is_member(family_id) and user_id = auth.uid());
drop policy if exists "notizen löschen" on public.recipe_notes;
create policy "notizen löschen" on public.recipe_notes for delete using (user_id = auth.uid());
create table if not exists public.board_posts (id uuid primary key default gen_random_uuid(), family_id uuid not null references public.families(id) on delete cascade, user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, body text not null check (char_length(body) between 1 and 200), created_at timestamptz not null default now());
alter table public.board_posts enable row level security;
drop policy if exists "pinnwand lesen" on public.board_posts;
create policy "pinnwand lesen" on public.board_posts for select using (public.is_member(family_id));
drop policy if exists "pinnwand schreiben" on public.board_posts;
create policy "pinnwand schreiben" on public.board_posts for insert with check (public.is_member(family_id) and user_id = auth.uid());
drop policy if exists "pinnwand löschen" on public.board_posts;
create policy "pinnwand löschen" on public.board_posts for delete using (user_id = auth.uid());
create table if not exists public.recipe_collections (id uuid primary key default gen_random_uuid(), family_id uuid not null references public.families(id) on delete cascade, name text not null check (char_length(name) between 1 and 30), emoji text not null default '📁', recipe_ids text[] not null default '{}', created_by uuid default auth.uid() references auth.users(id) on delete set null, created_at timestamptz not null default now());
alter table public.recipe_collections enable row level security;
drop policy if exists "sammlungen alles" on public.recipe_collections;
create policy "sammlungen alles" on public.recipe_collections for all using (public.is_member(family_id)) with check (public.is_member(family_id));
create table if not exists public.recipes (id text primary key, data jsonb not null, active boolean not null default true, source text, created_at timestamptz not null default now());
alter table public.recipes enable row level security;
drop policy if exists "rezepte lesen" on public.recipes;
create policy "rezepte lesen" on public.recipes for select to authenticated using (active);
do $$ begin alter publication supabase_realtime add table public.recipe_notes; exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table public.board_posts; exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table public.recipe_collections; exception when others then null; end $$;
select 'fertig' as ok;
